examples.template:
VStack(alignment: .leading, spacing: 8) {
    MonarchMoney(minorUnits: {{items.0.amount}}, currencyCode: {{items.0.currency}}, locale: Locale(identifier: {{items.0.locale}}))
    MonarchMoney(minorUnits: {{items.1.amount}}, currencyCode: {{items.1.currency}}, locale: Locale(identifier: {{items.1.locale}}))
    MonarchMoney(minorUnits: {{items.2.amount}}, currencyCode: {{items.2.currency}}, locale: Locale(identifier: {{items.2.locale}}))
    MonarchMoney(minorUnits: {{items.3.amount}}, currencyCode: {{items.3.currency}}, locale: Locale(identifier: {{items.3.locale}}))
}

examples.code:
VStack(alignment: .leading, spacing: 8) {
    MonarchMoney(minorUnits: 129_900, currencyCode: "USD", locale: Locale(identifier: "en-US"))
    MonarchMoney(minorUnits: 129_900, currencyCode: "EUR", locale: Locale(identifier: "de-DE"))
    MonarchMoney(minorUnits: 12_990_000, currencyCode: "INR", locale: Locale(identifier: "en-IN"))
    MonarchMoney(minorUnits: 4500, currencyCode: "JPY", locale: Locale(identifier: "ja-JP"))
}

VStack(alignment: .trailing) {
    MonarchMoney(1_250_000, currencyCode: "EUR", notation: .compact, textStyle: .title)
    MonarchMoney(42, currencyCode: "USD", signDisplay: .exceptZero)
    MonarchMoney(-42, currencyCode: "USD", usesAccountingSign: true, tonesNegative: true)
    MonarchMoney(nil, currencyCode: "USD")
}
